// Pega os dados da linha que disparou o trigger
const row = $input.first().json;

// Mapeamento exato das suas colunas
const idRoteiro     = row['ID do roteiro']                    || '';
const nomeCenario   = row['Nome do cenário']                  || '';
const urlTela       = row['URL da tela']                      || '';
const urlLogin      = row['URL de Login']                     || ''; // coluna nova sugerida
const dadosTeste    = row['Dados de teste']                   || '';
const passosManuais = row['Passos manuais']                   || '';
const resultadoEsperado = row['Resultado esperado']           || '';
const observacoesQA = row['Observações do QA']                || '';

// Validação — só processa se o trigger estiver TRUE
const pronto = row['Roteiro pronto para automação'];
if (String(pronto).toUpperCase() !== 'TRUE') {
  return [{ json: { skip: true, motivo: 'Roteiro não marcado como pronto' } }];
}

// Gera nome do arquivo fs-friendly a partir do ID + nome do cenário
const fileSlug = `${idRoteiro}-${nomeCenario}`
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')  // remove acentos
  .replace(/\s+/g, '-')             // espaços viram hífens
  .replace(/[^a-z0-9-]/g, '')       // remove caracteres especiais
  .replace(/-+/g, '-');             // hífens duplos viram um só

// Monta o markdown no formato exato que o Playwright Generator espera
const testPlan = `# ${nomeCenario}

## Contexto

- **ID do Roteiro:** ${idRoteiro}
- **URL de Login:** ${urlLogin || 'N/A'}
- **URL da Tela:** ${urlTela}

## Dados de Teste

${dadosTeste}

## Test Scenarios

### 1. ${nomeCenario}

**Seed:** \`tests/seed.spec.ts\`

#### 1.1 ${nomeCenario}

**Steps:**
${passosManuais
  .split('\n')
  .filter(p => p.trim() !== '')
  .map((p, i) => `${i + 1}. ${p.trim()}`)
  .join('\n')}

**Expected Results:**
${resultadoEsperado
  .split('\n')
  .filter(r => r.trim() !== '')
  .map(r => `- ${r.trim()}`)
  .join('\n')}

${observacoesQA ? `## Observações do QA\n${observacoesQA}` : ''}
`;

return [{
  json: {
    idRoteiro,
    nomeCenario,
    urlTela,
    urlLogin,
    dadosTeste,
    testPlan,
    fileName: `${fileSlug}.md`,          // para salvar em specs/
    fileNameSpec: `${fileSlug}.spec.ts`,  // para salvar em tests/ depois
    fileSlug
  }
}];

